// Read targets from MONITOR_TARGETS env. Expected JSON array of:
//   {name, url, expect_status, timeout_ms?}

const raw = $env.MONITOR_TARGETS || '[]';
let targets;
try {
  targets = JSON.parse(raw);
} catch (e) {
  throw new Error('MONITOR_TARGETS env must be valid JSON array, got: ' + raw.slice(0, 100));
}

if (!Array.isArray(targets) || targets.length === 0) {
  return [{ json: { skipped: true, reason: 'no targets configured' } }];
}

// Each target becomes one item in the next node
return targets.map(t => ({ json: {
  name: t.name || t.url,
  url: t.url,
  expectStatus: t.expect_status || 200,
  timeoutMs: t.timeout_ms || 10000,
} }));

// Health check returned 2xx (or matched expected status). State = up.

const input = $input.first();
const target = ($('Load Targets').first() && $('Load Targets').first().json) || {};
const statusCode = (input.json && input.json.statusCode) || 200;

return [{ json: {
  name: target.name || 'unknown',
  url: target.url || 'unknown',
  state: 'up',
  statusCode,
  checkedAt: new Date().toISOString(),
} }];

// Health check failed (network error, non-2xx, timeout). State = down.

const input = $input.first();
const target = ($('Load Targets').first() && $('Load Targets').first().json) || {};
const err = (input.json && input.json.error) || {};

return [{ json: {
  name: target.name || 'unknown',
  url: target.url || 'unknown',
  state: 'down',
  statusCode: (input.json && input.json.statusCode) || 0,
  errorMessage: err.message || 'request failed',
  checkedAt: new Date().toISOString(),
} }];

// State-change detection: alert only on transitions.
// We persist the last known state per target in $getWorkflowStaticData.
// Same target hitting the same state on 5 consecutive cycles = no alert spam.

const input = $input.first().json;
const data = $getWorkflowStaticData('global');
data.lastStates = data.lastStates || {};
const lastStates = data.lastStates;

const key = input.name;
const prevState = lastStates[key] || null;
const currState = input.state;

let transition = null;
if (prevState && prevState !== currState) {
  transition = `${prevState}-to-${currState}`;
}

lastStates[key] = currState;

return [{ json: {
  ...input,
  prevState,
  transition,
  shouldAlert: !!transition,
} }];

// Fallback for alert delivery failure. Log structured error, do not crash workflow.
const err = ($input.first().json && $input.first().json.error) || {};
return [{ json: {
  ok: false,
  fallback: true,
  errorMessage: err.message || 'alert delivery failed',
  errorName: err.name || 'AlertDeliveryError',
  loggedAt: new Date().toISOString(),
} }];
